import {layerState} from './folders.js';
import {poseGuide,guideEdges,moveGuideJoint,validateGuide} from './drawing-reference.js';
import {drawRig} from './pose-ui.js';
import {rasterStroke,decodePixels,rasterPoints} from './raster.js';
const NS='http://www.w3.org/2000/svg';
const node=(name,attrs={})=>{const e=document.createElementNS(NS,name);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;};
export function drawSkeleton(svg,guide,handles=false){const j=guide.joints;for(const [a,b]of guideEdges(guide.state)){svg.append(node('line',{x1:j[a][0],y1:j[a][1],x2:j[b][0],y2:j[b][1],stroke:'#33869d','stroke-width':4,'stroke-linecap':'round'}));}const head=j.head,neck=j.neck,r=Math.max(12,Math.hypot(head[0]-neck[0],head[1]-neck[1]));svg.append(node('ellipse',{cx:head[0],cy:head[1],rx:r*.78,ry:r,fill:'none',stroke:'#33869d','stroke-width':3}));for(const [id,[x,y]]of Object.entries(j))svg.append(node('circle',{cx:x,cy:y,r:handles?7:3,fill:handles?'#f0bd78':'#33869d',stroke:'#172c36','stroke-width':1,'data-guide-joint':id,...(handles?{tabindex:0,role:'button','aria-label':'Move '+id+' joint'}:{})}));}
export async function guideRaster(guide,transform,id){const svg=node('svg',{width:600,height:600,viewBox:'0 0 600 600'});if(guide.kind==='pose')drawSkeleton(svg,guide);else{drawRig(svg,guide.state,600,600);for(const child of [...svg.children])if(!child.hasAttribute('data-hair-face')&&!child.hasAttribute('data-hair-guide'))child.remove();}
 const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const image=new Image();image.src=url;await image.decode();const c=document.createElement('canvas');c.width=c.height=600;const ctx=c.getContext('2d');ctx.drawImage(image,0,0);const stroke=rasterStroke(ctx.getImageData(0,0,600,600).data,600,600,0,0,id);c.width=c.height=1;stroke.guide=structuredClone(guide);stroke.raster.transform=[...transform];stroke.points=rasterPoints(stroke.raster);validateGuide(stroke);return stroke;}finally{URL.revokeObjectURL(url);}}
export function initReferenceEditor({$,getBoard,commit,blocked,status}){const dialog=$('reference-editor'),svg=$('reference-joints');let source=null,guide=null,layerId=null,base=null,drag=null,past=[],future=[],opened=false;
 function error(e){$('reference-edit-error').textContent=e?.message||String(e||'');}
 function render(){svg.replaceChildren();if(!source)return;const [a,b,c,d,e,f]=source.raster.transform,det=a*d-b*c;
  for(const layer of base.layers){if(layer.id===layerId||!layer.visible)continue;for(const s of layer.strokes){if(s.brush!=='raster'||s.guide?.kind==='pose'||s.guide?.kind==='hair')continue;const r=s.raster,[u,v,w,z,x,y]=r.transform,canvas=document.createElement('canvas');canvas.width=r.width;canvas.height=r.height;canvas.getContext('2d').putImageData(new ImageData(decodePixels(r.data),r.width,r.height),0,0);svg.append(node('image',{href:canvas.toDataURL(),width:r.width,height:r.height,opacity:layer.opacity,transform:`matrix(${(d*u-c*v)/det} ${(a*v-b*u)/det} ${(d*w-c*z)/det} ${(a*z-b*w)/det} ${(d*(x-e)-c*(y-f))/det} ${(a*(y-f)-b*(x-e))/det})`}));canvas.width=canvas.height=1;}}
  drawSkeleton(svg,guide,true);$('reference-edit-undo').disabled=!past.length;$('reference-edit-redo').disabled=!future.length;}
 const PRESETS='unruly-reference-presets-v1';
 function presets(){const raw=localStorage.getItem(PRESETS);if(raw&&raw.length>524288)throw Error('Edited pose library is too large');const list=raw?JSON.parse(raw):[];if(!Array.isArray(list)||list.length>64)throw Error('Invalid edited pose library');const ids=new Set();for(const r of list){if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>80)throw Error('Invalid edited pose preset');ids.add(r.id);validateGuide({brush:'raster',guide:r.guide});if(r.guide.kind!=='pose')throw Error('Choose a pose preset');}return {raw,list};}
 function presetList(){try{$('reference-preset-list').replaceChildren(new Option('Choose edited pose…',''),...presets().list.map(r=>new Option(r.name,r.id)));}catch(e){error('Saved poses unavailable; original data preserved. '+e.message);}}
 function writePresets(next,raw){const text=JSON.stringify(next);if(text.length>524288||next.length>64)throw Error('Edited pose library limit');if(localStorage.getItem(PRESETS)!==raw)throw Error('Edited poses changed in another tab; reopen before saving');localStorage.setItem(PRESETS,text);presetList();}
 $('reference-preset-save').onclick=()=>{try{const name=$('reference-preset-name').value.trim();if(!name||name.length>80)throw Error('Name the edited pose (1–80 characters)');const {raw,list}=presets();writePresets([...list,{id:crypto.randomUUID(),name,guide:structuredClone(guide)}],raw);error('Edited pose saved on this device; download a backup for portability.');}catch(e){error(e);}};
 $('reference-preset-load').onclick=()=>{try{const r=presets().list.find(r=>r.id===$('reference-preset-list').value);if(!r)throw Error('Choose a saved edited pose');past.push(guide);future=[];guide=structuredClone(r.guide);render();error('');}catch(e){error(e);}};
 $('reference-preset-backup').onclick=()=>{try{const url=URL.createObjectURL(new Blob([JSON.stringify(presets().list)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='unruly-edited-poses.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error(e);}};
 $('reference-preset-import').onchange=async()=>{const input=$('reference-preset-import'),file=input.files[0];input.value='';if(!file)return;try{if(file.size>524288)throw Error('Pose backup exceeds 512 KiB');const {raw,list}=presets(),incoming=JSON.parse(await file.text());if(!Array.isArray(incoming)||incoming.length>64)throw Error('Invalid pose backup');for(const r of incoming){if(typeof r?.name!=='string'||!r.name.trim()||r.name.length>80)throw Error('Invalid pose name');validateGuide({brush:'raster',guide:r.guide});if(r.guide.kind!=='pose')throw Error('Invalid pose preset');}writePresets([...list,...incoming.map(r=>({...r,id:crypto.randomUUID()}))],raw);error('Imported edited poses with fresh IDs.');}catch(e){error(e);}};
 function close(){if(drag)guide=drag.before;drag=null;opened=false;dialog.close();}
 function open(id){if(blocked())return;try{base=getBoard();const layer=base.layers.find(l=>l.id===id);if(!layer||layerState(base,layer).locked||!layerState(base,layer).visible)throw Error('Show and unlock the pose layer before editing');source=layer.strokes.find(s=>s.guide?.kind==='pose');if(!source)throw Error('Choose a pose layer');layerId=id;const [a,b,c,d]=source.raster.transform,ratio=Math.hypot(a,b)/Math.hypot(c,d);svg.style.width='min(100%, '+(55*ratio)+'dvh)';svg.style.aspectRatio=String(ratio);svg.style.height='auto';svg.style.marginInline='auto';svg.setAttribute('preserveAspectRatio','none');guide=structuredClone(source.guide);past=[];future=[];error('');opened=true;dialog.showModal();render();presetList();}catch(e){status(e.message,true);}}
 svg.addEventListener('keydown',e=>{const id=e.target.dataset.guideJoint,delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!id||!delta)return;e.preventDefault();const before=structuredClone(guide),p=guide.joints[id],step=e.shiftKey?10:1;guide=moveGuideJoint(guide,id,p.map((v,i)=>Math.max(8,Math.min(592,v+delta[i]*step))));past.push(before);if(past.length>50)past.shift();future=[];render();svg.querySelector('[data-guide-joint="'+id+'"]')?.focus();});
 svg.addEventListener('pointerdown',e=>{const id=e.target.dataset.guideJoint;if(!id||drag)return;drag={pointer:e.pointerId,joint:id,before:structuredClone(guide)};svg.setPointerCapture(e.pointerId);e.preventDefault();});
 svg.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());try{guide=moveGuideJoint(drag.before,drag.joint,[Math.max(8,Math.min(592,p.x)),Math.max(8,Math.min(592,p.y))]);render();}catch(err){error(err);}});
 function end(e,cancel=false){if(!drag||drag.pointer!==e.pointerId)return;const before=drag.before;drag=null;if(cancel)guide=before;else if(JSON.stringify(before)!==JSON.stringify(guide)){past.push(before);if(past.length>50)past.shift();future=[];}render();}
 svg.addEventListener('pointerup',e=>end(e));svg.addEventListener('pointercancel',e=>end(e,true));svg.addEventListener('lostpointercapture',e=>end(e,true));
 $('reference-edit-undo').onclick=()=>{if(past.length){future.push(guide);guide=past.pop();render();}};$('reference-edit-redo').onclick=()=>{if(future.length){past.push(guide);guide=future.pop();render();}};
 dialog.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,select')){e.preventDefault();e.stopPropagation();$(e.shiftKey?'reference-edit-redo':'reference-edit-undo').click();}});$('reference-edit-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 $('reference-edit-apply').onclick=async()=>{const button=$('reference-edit-apply');button.disabled=true;try{if(getBoard()!==base)throw Error('Board changed; close and reopen the pose');const stroke=await guideRaster(guide,source.raster.transform,source.id);if(getBoard()!==base)throw Error('Board changed; close and reopen the pose');commit(layerId,stroke,base);close();}catch(e){error(e);}finally{button.disabled=false;}};
 return {open,editing:()=>opened};
}
export {poseGuide};
